<?php
declare(strict_types=1);
return function (\PDO $pdo): void { $pdo->exec('CREATE TABLE IF NOT EXISTS appointments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, patient_pid VARCHAR(30) NOT NULL, patient_name VARCHAR(255) NOT NULL, patient_birth_date DATE NULL, appointment_at DATETIME NOT NULL, deptid VARCHAR(100) NULL, department_name VARCHAR(255) NULL, doctor_personnel_nr VARCHAR(30) NULL, doctor_name VARCHAR(255) NULL, doctor_login_id VARCHAR(100) NULL, nurse_personnel_nr VARCHAR(30) NULL, nurse_name VARCHAR(255) NULL, nurse_login_id VARCHAR(100) NULL, notes TEXT NULL, created_by BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_appointments_time (appointment_at), INDEX idx_appointments_patient (patient_pid)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4'); };
